javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    function getSectionPath(sectionType) {
        if (sectionType === 'composition') {
            return 'selectedElement';
        }
        if (sectionType === 'data') {
            return 'selectedDataResource';
        }
        if (sectionType === 'state') {
            return 'selectedClientState';
        }
        if (sectionType === 'scripts') {
            return 'selectedClientScript';
        }
    };

    function getSelectedTab(tabName) {
        if (tabName === 'event') {
            return 'events';
        }
        if (tabName === 'property') {
            return 'config';
        }
        if (tabName.includes('style')) {
            return 'style';
        }

        return 'config';
    };

    return {
        route: "edit",
        fields: {
            experienceId: event.payload.experienceId,
            mode: event.payload.mode,
            routeId: event.payload.routeId,
            screenId: event.payload.screenId
        },
        params: {
            parentScreenId: event.payload.parentScreen || null,
            parentElementId: event.payload.parentElement || null,
            isHeadlessViewport: event.payload.parentScreen ? true : null,
            [getSectionPath(event.payload.sectionType)]: event.payload.elementId,
            selectedAlert: event.payload.ruleSysId,
            ...event.payload.formFactorId && {
                selectedFormFactor: event.payload.formFactorId
            },
            selectedTab: getSelectedTab(event.payload.violationTab)
        },
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null,
        navigationOptions: null
    };
})

