/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const payload = event.payload;
    const {
        experienceId,
        parentScreenId,
        parentElement,
        mode
    } = payload;

    const URL = `/now/builder/ui/${mode === 'experience' ? 'experience-assistant': 'pc-assistant'}/${experienceId}/params/parent-screen-id/${parentScreenId}/parent-element-id/${parentElement}`;

    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: {
            url: URL
        },
        navigationOptions: null
    };
}
